import { test } from 'node:test';
import assert from 'node:assert/strict';

import { countryRatingChangeWl } from '../../src/indicators/countryRating.mjs';
import { RATING_SCALE, notchCalculator, notchChange } from '../../src/ratings/notch.mjs';

const expectedWl = (n) => (n <= 0 ? 0 : n === 1 ? 1 : 2);

test('normalises case and whitespace (AC-3)', () => {
  assert.equal(countryRatingChangeWl('a', ' A- '), 1);
  assert.equal(countryRatingChangeWl('bbb+', 'bb+'), 2);
  assert.equal(countryRatingChangeWl('\tBBB+\n', 'bbb'), 1);
  assert.equal(countryRatingChangeWl('aaa', 'AAA '), 0);
});

test('unchanged rating or upgrade gives WL 0 (AC-8, C3)', () => {
  for (const [p, c] of [['A', 'A'], ['A-', 'A'], ['CCC-', 'AAA'], ['AA+', 'AAA'], ['B', 'BB-']]) {
    assert.equal(countryRatingChangeWl(p, c), 0, `${p} -> ${c}`);
  }
});

test('1-notch downgrade gives WL 1 (AC-8)', () => {
  for (const [p, c] of [['BBB+', 'BBB'], ['BBB-', 'BB+'], ['AAA', 'AA+'], ['CCC', 'CCC-']]) {
    assert.equal(countryRatingChangeWl(p, c), 1, `${p} -> ${c}`);
  }
});

test('downgrade of 2 or more notches gives WL 2 (AC-8)', () => {
  for (const [p, c] of [['BBB+', 'BBB-'], ['BBB+', 'BB+'], ['AAA', 'AA'], ['BB', 'B-'], ['AAA', 'CCC-']]) {
    assert.equal(countryRatingChangeWl(p, c), 2, `${p} -> ${c}`);
  }
});

test('all 361 pairs follow the threshold rule on notchChange (AC-8)', () => {
  const totals = [0, 0, 0];
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const result = countryRatingChangeWl(p, c);
      assert.equal(result, expectedWl(notchChange(p, c)), `${p} -> ${c}`);
      assert.equal(typeof result, 'number');
      if (result === 0) assert.ok(Object.is(result, 0), `${p} -> ${c} is +0`);
      totals[result] += 1;
    }
  }
  assert.deepEqual(totals, [190, 18, 153]);
});

test('differs from notchCalculator only for 1 and 2 notch downgrades (AC-9, C6)', () => {
  assert.equal(notchCalculator('BBB+', 'BBB').wl, 0);
  assert.equal(countryRatingChangeWl('BBB+', 'BBB'), 1);

  const diffs = { 1: 0, 2: 0 };
  let equal = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const { notches, wl } = notchCalculator(p, c);
      const ind = countryRatingChangeWl(p, c);
      if (ind === wl) {
        equal += 1;
        assert.ok(notches !== 1 && notches !== 2, `${p} -> ${c} must differ`);
      } else {
        assert.ok(notches === 1 || notches === 2, `${p} -> ${c} unexpected divergence`);
        assert.equal(ind, wl + 1);
        diffs[notches] += 1;
      }
    }
  }
  assert.deepEqual(diffs, { 1: 18, 2: 17 });
  assert.equal(equal, 326);
