import { notchChange } from '../ratings/notch.mjs';

/**
 * Watchlist level for a change in a country's rating: 0 for unchanged or
 * upgraded, 1 for a 1-notch downgrade, 2 for a downgrade of 2 or more notches.
 * Intentionally differs from notchCalculator(...).wl on 1- and 2-notch
