}
/**
 * Rating notch calculator (REQ-06-02).
 *
 * Pure, synchronous and dependency-free. WL = Watchlist level (0-4, higher is
 * worse); this module only produces WL 0-2 from a rating change.
 */

/** The 19 ratings of the confirmed scale (C1), best first. */
export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

const INDEX_BY_RATING = new Map(RATING_SCALE.map((rating, index) => [rating, index]));

/** Renders any value for an error message without ever throwing. */
function describe(value) {
  try {
    return typeof value === 'string' ? JSON.stringify(value) : String(value);
  } catch {
    return Object.prototype.toString.call(value);
  }
}

/**
 * Validates one rating and returns its scale index.
 * Non-strings are rejected before any string method is called; strings are
 * trimmed and upper-cased, then looked up in a private Map.
 * @throws {RangeError} if the value is not one of the 19 scale ratings.
 */
function toIndex(value) {
  if (typeof value !== 'string') {
    throw new RangeError(`Invalid rating: expected a string, got ${describe(value)}`);
  }
  const index = INDEX_BY_RATING.get(value.trim().toUpperCase());
  if (index === undefined) {
    throw new RangeError(`Invalid rating: ${describe(value)} is not on the rating scale`);
  }
  return index;
}

/**
 * Signed notch change from `previous` to `current`: positive is a downgrade,
 * negative an upgrade, +0 unchanged.
 * Example: notchChange("BBB+", "BB+") === 3.
 * @param {string} previous
 * @param {string} current
 * @returns {number}
 * @throws {RangeError} if either rating is invalid.
 */
export function notchChange(previous, current) {
  const from = toIndex(previous);
  const to = toIndex(current);
  return to - from; // integer subtraction: equal indexes give +0, never -0
}

/**
 * Notch change, its direction and the resulting WL (downgrades only:
 * 2 notches -> WL 1, 3 or more -> WL 2, everything else WL 0).
 * Example: notchCalculator("BBB+", "BB+") -> { notches: 3, direction: "downgrade", wl: 2 }.
 * @param {string} previous
 * @param {string} current
 * @returns {{notches: number, direction: "downgrade"|"upgrade"|"unchanged", wl: number}}
 * @throws {RangeError} if either rating is invalid.
 */
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
  return { notches, direction, wl };
}
