// Integration tests for T-02 (REQ-03-12, Indicator 12): the public surface of
// src/indicators/countryRating.mjs, imported the way another POC module would.
// Expected values follow C1-C8 (C2: BBB+ -> BB+ is 3 notches; C3: upgrades -> WL 0;
// C6: Indicator 12 intentionally differs from notchCalculator(...).wl).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import * as ns from '../../../src/indicators/countryRating.mjs';
import { countryRatingChangeWl } from '../../../src/indicators/countryRating.mjs';
import { notchChange, notchCalculator } from '../../../src/ratings/notch.mjs';

const REPO_ROOT = fileURLToPath(new URL('../../../', import.meta.url));

const SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];
const pairs = [];
for (const p of SCALE) for (const c of SCALE) pairs.push([p, c]);

const INVALID = [
  '', '   ', 'BBB +', 'BBB++', 'AA−', 'CC', 'C', 'D', 'SD', 'NR', 'Baa1', 'AAA-',
  null, undefined, 7, {}, ['AAA'], true,
];
const label = (v) => {
  try { return typeof v === 'string' ? JSON.stringify(v) : String(v); } catch { return typeof v; }
};

const expectedWl = (n) => (n <= 0 ? 0 : n === 1 ? 1 : 2);

// ---------------------------------------------------------------- AC-3
test('AC-3: previous "a" and current " A- " is a 1-notch downgrade, WL 1', () => {
  assert.equal(countryRatingChangeWl('a', ' A- '), 1);
});

test('AC-3: case/whitespace variants give the same WL as the canonical values', () => {
  assert.equal(countryRatingChangeWl('bbb+', 'bb+'), 2);
  assert.equal(countryRatingChangeWl('\tBBB+\n', 'bbb'), 1);
  assert.equal(countryRatingChangeWl('aaa', 'AAA '), 0);
});

// ---------------------------------------------------------------- AC-8
test('AC-8: unchanged rating or upgrade returns 0 (C3)', () => {
  for (const [p, c] of [['A', 'A'], ['A-', 'A'], ['CCC-', 'AAA'], ['AA+', 'AAA'], ['B', 'BB-']]) {
    assert.equal(countryRatingChangeWl(p, c), 0, `${p} -> ${c}`);
  }
});

test('AC-8: 1-notch downgrade returns 1 (REQ-03-12)', () => {
  for (const [p, c] of [['BBB+', 'BBB'], ['BBB-', 'BB+'], ['AAA', 'AA+'], ['CCC', 'CCC-']]) {
    assert.equal(countryRatingChangeWl(p, c), 1, `${p} -> ${c}`);
  }
});

test('AC-8: downgrade of 2 or more notches returns 2 (REQ-03-12)', () => {
  for (const [p, c] of [['BBB+', 'BBB-'], ['BBB+', 'BB+'], ['AAA', 'AA'], ['BB', 'B-'], ['AAA', 'CCC-']]) {
    assert.equal(countryRatingChangeWl(p, c), 2, `${p} -> ${c}`);
  }
});

test('AC-8: boundaries n = -1, 0, 1, 2 and scale ends', () => {
  assert.equal(countryRatingChangeWl('A-', 'A'), 0); // n = -1
  assert.equal(countryRatingChangeWl('A', 'A'), 0); // n = 0
  assert.equal(countryRatingChangeWl('A', 'A-'), 1); // n = 1
  assert.equal(countryRatingChangeWl('A', 'BBB+'), 2); // n = 2
  assert.equal(countryRatingChangeWl('AAA', 'CCC-'), 2);
  assert.equal(countryRatingChangeWl('CCC-', 'AAA'), 0);
});

test('AC-8: all 361 pairs follow the threshold rule applied to notchChange', () => {
  assert.equal(pairs.length, 361);
  for (const [p, c] of pairs) {
    const wl = countryRatingChangeWl(p, c);
    assert.equal(wl, expectedWl(notchChange(p, c)), `${p} -> ${c}`);
    assert.equal(typeof wl, 'number', `${p} -> ${c}`);
    assert.ok([0, 1, 2].includes(wl), `${p} -> ${c}`);
    if (wl === 0) assert.ok(Object.is(wl, 0), `${p} -> ${c} must be +0`);
  }
});

test('AC-8: distribution over the 361 pairs is wl0 = 190, wl1 = 18, wl2 = 153', () => {
  const counts = { 0: 0, 1: 0, 2: 0 };
  for (const [p, c] of pairs) counts[countryRatingChangeWl(p, c)] += 1;
  assert.deepEqual(counts, { 0: 190, 1: 18, 2: 153 });
});

// ---------------------------------------------------------------- AC-9
test('AC-9 (C6): calculator WL is 0 and Indicator 12 is 1 for BBB+ -> BBB', () => {
  assert.equal(notchCalculator('BBB+', 'BBB').wl, 0);
  assert.equal(countryRatingChangeWl('BBB+', 'BBB'), 1);
});

test('AC-9: calculator and Indicator 12 differ only for 1 notch (18 pairs) and 2 notches (17 pairs)', () => {
  let oneNotch = 0;
  let twoNotch = 0;
  let equal = 0;
  for (const [p, c] of pairs) {
    const calc = notchCalculator(p, c);
    const wl = countryRatingChangeWl(p, c);
    if (calc.wl === wl) { equal += 1; continue; }
    if (calc.notches === 1) {
      oneNotch += 1;
      assert.equal(calc.wl, 0, `${p} -> ${c}`);
      assert.equal(wl, 1, `${p} -> ${c}`);
    } else if (calc.notches === 2) {
      twoNotch += 1;
      assert.equal(calc.wl, 1, `${p} -> ${c}`);
      assert.equal(wl, 2, `${p} -> ${c}`);
    } else {
      assert.fail(`unexpected divergence for ${p} -> ${c} (notches ${calc.notches})`);
    }
  }
  assert.equal(oneNotch, 18);
  assert.equal(twoNotch, 17);
  assert.equal(equal, 326);
});

// ---------------------------------------------------------------- AC-10
test('AC-10 (C7): countryRatingChangeWl takes exactly two parameters', () => {
  assert.equal(countryRatingChangeWl.length, 2);
});

test('AC-10 (C7): no state, no caching - repeated calls in alternating order', () => {
  const results = [
    countryRatingChangeWl('BBB+', 'BBB-'),
    countryRatingChangeWl('BBB+', 'BBB'),
    countryRatingChangeWl('BBB+', 'BBB-'),
    countryRatingChangeWl('BBB+', 'BBB'),
  ];
  assert.deepEqual(results, [2, 1, 2, 1]);
});

// ---------------------------------------------------------------- Scope
test('Scope: the module exports only countryRatingChangeWl', () => {
  assert.deepEqual(Object.keys(ns), ['countryRatingChangeWl']);
});

// ---------------------------------------------------------------- AC-11
test('AC-11 (C1): every invalid value throws RangeError in either position', () => {
  for (const bad of INVALID) {
    assert.throws(() => countryRatingChangeWl(bad, 'BBB'), RangeError, `previous = ${label(bad)}`);
    assert.throws(() => countryRatingChangeWl('BBB', bad), RangeError, `current = ${label(bad)}`);
  }
});

test('AC-11: missing arguments throw RangeError', () => {
  assert.throws(() => countryRatingChangeWl(), RangeError);
  assert.throws(() => countryRatingChangeWl('AAA'), RangeError);
});

test('AC-11: ratings outside the 19-step scale are never swallowed (no 0/null/undefined)', () => {
  let result = 'not-called';
  assert.throws(() => { result = countryRatingChangeWl('CC', 'AAA'); }, RangeError);
  assert.throws(() => { result = countryRatingChangeWl('AAA', 'D'); }, RangeError);
  assert.equal(result, 'not-called');
});

test('AC-11: errors are the same RangeError type that notchChange throws (propagated, not wrapped)', () => {
  for (const bad of INVALID) {
    let fromIndicator;
    let fromNotch;
    try { countryRatingChangeWl(bad, 'BBB'); } catch (e) { fromIndicator = e; }
    try { notchChange(bad, 'BBB'); } catch (e) { fromNotch = e; }
    assert.ok(fromIndicator instanceof RangeError, label(bad));
    assert.ok(fromNotch instanceof RangeError, label(bad));
    assert.equal(fromIndicator.message, fromNotch.message, label(bad));
  }
});

// ---------------------------------------------------------------- AC-12
const walk = (dir) => {
  const out = [];
  for (const name of readdirSync(dir)) {
    const full = path.join(dir, name);
    if (statSync(full).isDirectory()) out.push(...walk(full));
    else out.push(full);
  }
  return out;
};

test('AC-12: src/ has no console/process/node:/fetch/require usage', () => {
  const re = /console\.|process\.|from ['"]node:|fetch\(|require\(/;
  const hits = [];
  for (const file of walk(path.join(REPO_ROOT, 'src'))) {
    readFileSync(file, 'utf8').split('\n').forEach((line, i) => {
      if (re.test(line)) hits.push(`${path.relative(REPO_ROOT, file)}:${i + 1}: ${line}`);
    });
  }
  assert.deepEqual(hits, []);
});

test('AC-12: countryRating.mjs imports only notchChange from ../ratings/notch.mjs; notch.mjs imports nothing', () => {
  const re = /^\s*import|import\(/;
  const importLines = (rel) => readFileSync(path.join(REPO_ROOT, rel), 'utf8')
    .split('\n').filter((line) => re.test(line));
  assert.deepEqual(
    importLines('src/indicators/countryRating.mjs'),
    ["import { notchChange } from '../ratings/notch.mjs';"],
  );
  assert.deepEqual(importLines('src/ratings/notch.mjs'), []);
});

test('AC-12: package.json declares no dependencies of any kind', () => {
  const pkg = JSON.parse(readFileSync(path.join(REPO_ROOT, 'package.json'), 'utf8'));
  for (const key of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) {
    assert.ok(!(key in pkg), `${key} must not be present`);
  }
});

test('AC-12 (C8): calling both modules writes nothing to stdout/stderr and exits 0', () => {
  const script =
    "import {countryRatingChangeWl} from './src/indicators/countryRating.mjs'; " +
    "import {notchCalculator} from './src/ratings/notch.mjs'; " +
    "countryRatingChangeWl('BBB+','BBB-'); notchCalculator('A','BBB');";
  const res = spawnSync(process.execPath, ['--input-type=module', '-e', script], {
    cwd: REPO_ROOT, encoding: 'utf8',
  });
  assert.equal(res.status, 0, res.stderr);
  assert.equal(res.stdout, '');
  assert.equal(res.stderr, '');
});

// ---------------------------------------------------------------- AC-13
const countOf = (output, name) => {
  const m = output.match(new RegExp(`^# ${name} (\\d+)`, 'm'));
  assert.ok(m, `no "# ${name}" line in TAP output`);
  return Number(m[1]);
};
const runNode = (args, env = {}) => spawnSync(
  process.execPath, ['--test', '--test-reporter=tap', ...args],
  { cwd: REPO_ROOT, encoding: 'utf8', env: { ...process.env, ...env } },
);

// The full run below includes this very file; the guard variable stops it recursing.
test('AC-13: node --test from the repo root exits 0, fails nothing, and runs both unit files',
  { skip: process.env.T02_QA_NESTED === '1' && 'nested run', timeout: 120000 },
  () => {
    const notchUnit = runNode(['test/ratings/notch.test.mjs']);
    const countryUnit = runNode(['test/indicators/countryRating.test.mjs']);
    assert.equal(notchUnit.status, 0, notchUnit.stdout);
    assert.equal(countryUnit.status, 0, countryUnit.stdout);
    const unitTotal = countOf(notchUnit.stdout, 'tests') + countOf(countryUnit.stdout, 'tests');
    assert.ok(unitTotal > 0);

    const full = runNode([], { T02_QA_NESTED: '1' });
    assert.equal(full.status, 0, full.stdout);
    assert.equal(countOf(full.stdout, 'fail'), 0);
    assert.ok(
      countOf(full.stdout, 'tests') >= unitTotal,
      `full run total ${countOf(full.stdout, 'tests')} < unit sum ${unitTotal}`,
    );
  });

test('AC-13 (C2): no test or source expects BBB+ -> BB+ to be 2 notches / calculator WL 1', () => {
  const re = /BBB\+['"]?\s*,\s*['"]?BB\+|BBB\+\s*(->|→)\s*BB\+/;
  const bad = /notches['"]?\s*:\s*2\b|\bwl['"]?\s*:\s*1\b/;
  const files = [
    ...walk(path.join(REPO_ROOT, 'src')),
    ...walk(path.join(REPO_ROOT, 'test')),
  ].filter((f) => f.endsWith('.mjs'));
  const offenders = [];
  let hitCount = 0;
  for (const file of files) {
    const lines = readFileSync(file, 'utf8').split('\n');
    lines.forEach((line, i) => {
