/**
 * Indicator 12 - country rating change (REQ-03-12).
 *
 * Pure and synchronous. WL = Watchlist level (0-4, higher is worse).
 */
import { notchChange } from '../ratings/notch.mjs';

/**
 * Watchlist level for a change in a country's rating: 0 for unchanged or
 * upgraded, 1 for a 1-notch downgrade, 2 for a downgrade of 2 or more notches.
 * Intentionally differs from notchCalculator(...).wl on 1- and 2-notch
 * downgrades. Trimming, case-folding and validation come from notchChange.
 * Example: countryRatingChangeWl("BBB+", "BBB") === 1.
 * @param {string} previous
 * @param {string} current
 * @returns {0|1|2}
 * @throws {RangeError} if either rating is invalid (from notchChange).
 */
export function countryRatingChangeWl(previous, current) {
  const notches = notchChange(previous, current);
  if (notches <= 0) return 0;
  return notches === 1 ? 1 : 2;
}
